documents.spec:
yamaa: "1.0"
type: spec
domain: XX
keys: [USUBJID, SRC, SEQ]
output: {path: out.csv, columns: [USUBJID, SRC, SEQ, ORD]}
input:
  DM: {path: dm.csv, key: [USUBJID], types: {AGE: int, RFSTDTC: date}}
  AE: {path: ae.csv, types: {AESEQ: int, AESTDTC: date}}
  LB: {path: lb.csv, types: {LBSEQ: int}}
rows:
  - {id: subjects, dataset: DM, derivations: {USUBJID: DM.USUBJID, SRC: "'DM'", SEQ: 0}}
  - {id: events, dataset: AE, derivations: {USUBJID: AE.USUBJID, SRC: "'AE'", SEQ: AE.AESEQ}}
columns:
  - {name: USUBJID, type: str}
  - {name: SRC, type: str}
  - {name: SEQ, type: int}
  - {name: ORD, type: int, derivation: {row_number: {window: {order_by: [DM.AGE]}}}}

documents.base:
