  LB: {path: lb.csv, types: {LBSEQ: int}}
columns:
  - {name: USUBJID, type: str, derivation: DM.USUBJID}
  - {name: ORD, type: int, derivation: {row_number: {window: {order_by: [DM.AGE]}}}}

